const TOOL_R=24,HELD={},TOOL_MAT=['#c9a06a','#ff9a5c','#c3d0ee','#6ff2ff']; // matière par rang : bois, cuivre, fer, diamant
const TOOLS={pick1:['pick',1],pick2:['pick',2],pick3:['pick',3],pick4:['pick',4],sword1:['sword',1],sword2:['sword',2],sword3:['sword',3],sword4:['sword',4],bow:['bow',1],torch:['torch',1]};
