// outil tourné, centré sur sa prise (toile de 2*TOOL_R+1) ; angle arrondi au 12e de radian pour limiter le cache
function heldTool(id,a,v=0){const t=TOOLS[id];if(!t)return null;a=Math.round(a*12)/12;const key=id+'|'+a+'|'+v;if(HELD[key])return HELD[key];
  const ps=TOOL_POSE[t[0]];return HELD[key]=rotPix(toolBase(t[0],t[1],v),a,ps.g[0],ps.g[1])}
// objet quelconque (bombe, potion, bloc, minerai) : son icône posée dans la main
function heldItem(id){const key='i|'+id,ic=ICON[id];if(HELD[key]||!ic)return HELD[key]||null;const N=TOOL_R*2+1,c=mk(N,N),g=c.getContext('2d');g.imageSmoothingEnabled=false;g.drawImage(ic,TOOL_R-6,TOOL_R-12,12,12);return HELD[key]=c}
// ce que tient le héros selon la pose q (sw : rotation de la pose, fl : flamme alternée)
function heldFn(id){const t=TOOLS[id];if(!t)return()=>heldItem(id);const ps=TOOL_POSE[t[0]];return q=>heldTool(id,ps.rest+(q.sw||0)*ps.k,t[0]==='torch'&&q.fl?1:0)}
