const BOON_BY=Object.fromEntries(BOONS.map(b=>[b.id,b]));
// BOON : niveaux acquis · boonPick : les 3 offres en attente (jeu figé) · boonSeq : rang du tirage · boonDay : dernier jour servi · boonRe : relances restantes
let BOON={},boonPick=null,boonSeq=0,boonDay=-1,boonRe=1,boonT=0,boonAuto=false,boonOff=false,boonPulseT=0,titheT=20;
const bv=id=>BOON[id]||0,bval=id=>(BOON_BY[id].v||0)*bv(id);
const boonDesc=(b,lv)=>tr(b.d).replace('{v}',(b.v||0)*Math.max(1,lv));
function boonReset(){BOON={};boonPick=null;boonSeq=0;boonDay=-1;boonRe=1;boonT=0;boonPulseT=0;titheT=20}
function rollBoons(){const r=mulberry((SEED*31+boonSeq*977+7)|0),pool=BOONS.filter(b=>!b.max||bv(b.id)<b.max),wt=b=>b.rare?1:2.4,out=[];
  while(out.length<3&&pool.length){let k=r()*pool.reduce((a,b)=>a+wt(b),0),i=0;for(;i<pool.length-1;i++){k-=wt(pool[i]);if(k<0)break}out.push(pool.splice(i,1)[0].id)}return out}
function offerBoons(){boonPick=rollBoons();boonT=0;panel=null;cursorItem=null;mining=null;mouse.l=mouse.r=false;for(const k in keys)keys[k]=false;touch.l=touch.r=touch.j=touch.d=touch.a=false;if(!boonAuto){sfx.ach();buzz(30)}}
function rerollBoons(){if(!boonPick||boonRe<=0)return;boonRe--;boonSeq++;boonPick=rollBoons();boonT=.2;sfx.place()}
// coût de recrutement du joueur (Intendance) ; l'ennemi paie toujours le prix fort
function ucost(team,kind){const c=UNITS[kind].cost,k=team===0?bval('supply'):0;return k?Object.fromEntries(Object.entries(c).map(([r,v])=>[r,Math.max(1,Math.ceil(v*(1-k/100)))])):c}
function chooseBoon(i,force=false){if(!boonPick||(!force&&boonT<.35))return;const id=boonPick[i];if(!id)return;const b=BOON_BY[id],base=bases[0],p=player,lv=BOON[id]=bv(id)+1;
  boonPick=null;boonSeq++;boonDay=Math.floor(time/dayLen);stats.boons=(stats.boons||0)+1;
  if(id==='crew')for(let k=0;k<2;k++)recruit(0,'miner',true);
  else if(id==='levy')for(let k=0;k<3;k++)recruit(0,'warrior',true);
  else if(id==='golem')recruit(0,'golem',true);
  else if(id==='cache')addLoot(base.storage,{copper:25,iron:10,silver:4});
  else if(id==='bombs'){const left=addItem('bomb',8);if(left>0)dropItem(p.x+5,p.y,'bomb',left)}
  else if(id==='bastion'){base.core.maxhp+=400;base.core.hp+=400}
  else if(id==='heart'){p.maxhp+=b.v;if(!p.dead)p.hp=p.maxhp}
  else if(id==='vigor'){const k=(1+b.v*lv/100)/(1+b.v*(lv-1)/100);for(const e of ents)if(e.type==='unit'&&e.team===0&&!e.dead){e.maxhp=Math.round(e.maxhp*k);e.hp=Math.min(e.maxhp,Math.round(e.hp*k))}}
  if(!boonAuto){sfx.buy();buzz(40);const c=BCAT[b.cat].c;burst(p.x+p.w/2,p.y+p.h/2,c,22,90,120,.9,1);pops.push({ring:1,x:p.x+p.w/2,y:p.y+p.h/2,t:.5,max:.5,col:c,r:34});toast('Bénédiction : '+tr(b.n),3.5,c)}
  if(stats.boons>=6)unlock('boon6');saveGame()}
