  ctx.fillStyle='#06060f';ctx.fillRect(x+1,y,w-2,1);ctx.fillRect(x+1,y+h-1,w-2,1);ctx.fillRect(x,y+1,1,h-2);ctx.fillRect(x+w-1,y+1,1,h-2);
  ctx.fillStyle=T.f;ctx.fillRect(x+1,y+1,w-2,h-2);
